import { createValidator } from '@enkaku/schema';
import { INVALID_PARAMS } from '@mokei/context-protocol';
import { RPCError } from '@mokei/context-rpc';
export function createPrompt(description, argumentsSchema, handler) {
    const validate = createValidator(argumentsSchema);
    const wrappedHandler = (request)=>{
        const validated = validate(request.arguments);
        if (validated.issues == null) {
            return handler({
                arguments: validated.value,
                client: request.client,
                signal: request.signal
            });
        }
        throw new RPCError(INVALID_PARAMS, 'Invalid prompt arguments', {
            issues: validated.issues.map((issue)=>({
                    message: issue.message,
                    path: issue.path
                }))
        });
    };
    return {
        description,
        argumentsSchema,
        handler: wrappedHandler
    };
}
export function createTool(description, inputSchema, handler) {
    const validate = createValidator(inputSchema);
    const wrappedHandler = (request)=>{
        const validated = validate(request.arguments);
        if (validated.issues == null) {
            return handler({
                arguments: validated.value,
                client: request.client,
                signal: request.signal
            });
        }
        throw new RPCError(INVALID_PARAMS, 'Invalid tool input', {
            issues: validated.issues.map((issue)=>({
                    message: issue.message,
                    path: issue.path
                }))
        });
    };
    return {
        description,
        inputSchema: inputSchema,
        handler: wrappedHandler
    };
}
export function toResourceHandlers(definitions) {
    const { list, listTemplates, read } = definitions;
    return {
        list: typeof list === 'function' ? list : ()=>({
                resources: list ?? []
            }),
        listTemplates: typeof listTemplates === 'function' ? listTemplates : ()=>({
                resourceTemplates: listTemplates ?? []
            }),
        read
    };
}
